from typing import List

class Solution:
    def subarrayBitwiseORs(self, arr: List[int]) -> int:
        res = set()
        cur = set()
        for x in arr:
            cur = {x | y for y in cur} | {x}
            res |= cur
        return len(res)

class Solution {
public:
    int subarrayBitwiseORs(vector<int>& arr) {
        unordered_set<int> res;
        unordered_set<int> cur;
        for (int x : arr) {
            unordered_set<int> nxt = {x};
            for (int y : cur) nxt.insert(x | y);
            cur = move(nxt);
            res.insert(cur.begin(), cur.end());
        }
        return res.size();
    }
};

class Solution {
    public int subarrayBitwiseORs(int[] arr) {
        Set<Integer> res = new HashSet<>();
        Set<Integer> cur = new HashSet<>();
        for (int x : arr) {
            Set<Integer> nxt = new HashSet<>();
            nxt.add(x);
            for (int y : cur) nxt.add(x | y);
            cur = nxt;
            res.addAll(cur);
        }
        return res.size();
    }
}

var subarrayBitwiseORs = function(arr) {
    const res = new Set();
    let cur = new Set();
    for (const x of arr) {
        const nxt = new Set([x]);
        for (const y of cur) nxt.add(x | y);
        cur = nxt;
        for (const v of cur) res.add(v);
    }
    return res.size;
};
